#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <omp.h>

#if defined(__AVX512F__) || (defined(__AVX2__) && defined(__FMA__))
#include <immintrin.h>
#endif

#if defined(__AVX512F__)
/* ---------------- AVX-512: 12 x 32 micro-kernel ---------------- */
#define MR 12
#define NR 32
#define KC 256
#define MB 8   /* A slivers per task  -> 96 rows  */
#define NB 4   /* B slivers per task  -> 128 cols */

#define DECL(i) __m512 c##i##0 = _mm512_setzero_ps(), c##i##1 = _mm512_setzero_ps();
#define FM(i) { __m512 t_ = _mm512_set1_ps(a[i]); \
    c##i##0 = _mm512_fmadd_ps(t_, b0, c##i##0); \
    c##i##1 = _mm512_fmadd_ps(t_, b1, c##i##1); }
#define ST(i) { float *p_ = c + (size_t)(i) * ldc; \
    if (acc) { c##i##0 = _mm512_add_ps(c##i##0, _mm512_loadu_ps(p_)); \
               c##i##1 = _mm512_add_ps(c##i##1, _mm512_loadu_ps(p_ + 16)); } \
    _mm512_storeu_ps(p_, c##i##0); _mm512_storeu_ps(p_ + 16, c##i##1); }

static inline void kern(int kc, const float *restrict a, const float *restrict b,
                        float *restrict c, long ldc, int acc)
{
    DECL(0) DECL(1) DECL(2) DECL(3) DECL(4) DECL(5)
    DECL(6) DECL(7) DECL(8) DECL(9) DECL(10) DECL(11)
#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        __m512 b0 = _mm512_load_ps(b), b1 = _mm512_load_ps(b + 16);
        FM(0) FM(1) FM(2) FM(3) FM(4) FM(5)
        FM(6) FM(7) FM(8) FM(9) FM(10) FM(11)
        a += MR; b += NR;
    }
    ST(0) ST(1) ST(2) ST(3) ST(4) ST(5)
    ST(6) ST(7) ST(8) ST(9) ST(10) ST(11)
}

#elif defined(__AVX2__) && defined(__FMA__)
/* ---------------- AVX2: 6 x 16 micro-kernel ---------------- */
#define MR 6
#define NR 16
#define KC 256
#define MB 16  /* 96 rows  */
#define NB 8   /* 128 cols */

#define DECL(i) __m256 c##i##0 = _mm256_setzero_ps(), c##i##1 = _mm256_setzero_ps();
#define FM(i) { __m256 t_ = _mm256_broadcast_ss(a + (i)); \
    c##i##0 = _mm256_fmadd_ps(t_, b0, c##i##0); \
    c##i##1 = _mm256_fmadd_ps(t_, b1, c##i##1); }
#define ST(i) { float *p_ = c + (size_t)(i) * ldc; \
    if (acc) { c##i##0 = _mm256_add_ps(c##i##0, _mm256_loadu_ps(p_)); \
               c##i##1 = _mm256_add_ps(c##i##1, _mm256_loadu_ps(p_ + 8)); } \
    _mm256_storeu_ps(p_, c##i##0); _mm256_storeu_ps(p_ + 8, c##i##1); }

static inline void kern(int kc, const float *restrict a, const float *restrict b,
                        float *restrict c, long ldc, int acc)
{
    DECL(0) DECL(1) DECL(2) DECL(3) DECL(4) DECL(5)
#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        __m256 b0 = _mm256_load_ps(b), b1 = _mm256_load_ps(b + 8);
        FM(0) FM(1) FM(2) FM(3) FM(4) FM(5)
        a += MR; b += NR;
    }
    ST(0) ST(1) ST(2) ST(3) ST(4) ST(5)
}

#else
/* ---------------- Generic (vector extensions): 8 x 12 ---------------- */
#define MR 8
#define NR 12
#define KC 256
#define MB 12
#define NB 8

typedef float v4f __attribute__((vector_size(16)));

static inline void kern(int kc, const float *restrict a, const float *restrict b,
                        float *restrict c, long ldc, int acc)
{
    v4f s[MR][3];
    for (int i = 0; i < MR; i++) { s[i][0] = (v4f){0}; s[i][1] = (v4f){0}; s[i][2] = (v4f){0}; }
    for (int k = 0; k < kc; k++) {
        v4f b0 = *(const v4f *)(b), b1 = *(const v4f *)(b + 4), b2 = *(const v4f *)(b + 8);
#pragma GCC unroll 8
        for (int i = 0; i < MR; i++) {
            float ai = a[i];
            v4f av = {ai, ai, ai, ai};
            s[i][0] += av * b0; s[i][1] += av * b1; s[i][2] += av * b2;
        }
        a += MR; b += NR;
    }
    for (int i = 0; i < MR; i++) {
        float *p = c + (size_t)i * ldc;
        if (acc) {
            v4f t[3];
            memcpy(t, p, sizeof t);
            s[i][0] += t[0]; s[i][1] += t[1]; s[i][2] += t[2];
        }
        memcpy(p, s[i], sizeof(float) * NR);
    }
}
#endif

/* ---------------- shared driver ---------------- */

static float *g_Ap = NULL, *g_Bp = NULL;
static size_t g_Acap = 0, g_Bcap = 0;
static int g_nt = 0;

static float *grow(float *p, size_t *cap, size_t need)
{
    if (need <= *cap) return p;
    free(p);
    size_t bytes = (need * sizeof(float) + 63) & ~(size_t)63;
    p = (float *)aligned_alloc(64, bytes);
    *cap = p ? need : 0;
    return p;
}

static int get_threads(void)
{
    int nt = omp_get_max_threads();
    FILE *f = fopen("/sys/fs/cgroup/cpu.max", "r");
    if (f) {
        char q[64]; long per;
        if (fscanf(f, "%63s %ld", q, &per) == 2 && strcmp(q, "max") != 0 && per > 0) {
            long qq = atol(q);
            int c = (int)((qq + per - 1) / per);
            if (c > 0 && c < nt) nt = c;
        }
        fclose(f);
    } else {
        f = fopen("/sys/fs/cgroup/cpu/cpu.cfs_quota_us", "r");
        if (f) {
            long qq = -1, per = 0;
            if (fscanf(f, "%ld", &qq) != 1) qq = -1;
            fclose(f);
            f = fopen("/sys/fs/cgroup/cpu/cpu.cfs_period_us", "r");
            if (f) {
                if (fscanf(f, "%ld", &per) != 1) per = 0;
                fclose(f);
            }
            if (qq > 0 && per > 0) {
                int c = (int)((qq + per - 1) / per);
                if (c > 0 && c < nt) nt = c;
            }
        }
    }
    return nt < 1 ? 1 : nt;
}

static inline int imin(int a, int b) { return a < b ? a : b; }

static void packA(const float *A, float *Ap, int n, int mpad, int s)
{
    int i0 = s * MR, rows = imin(MR, n - i0);
    for (int pc = 0; pc < n; pc += KC) {
        int kc = imin(KC, n - pc);
        float *d = Ap + (size_t)pc * mpad + (size_t)s * MR * kc;
        for (int r = 0; r < rows; r++) {
            const float *src = A + (size_t)(i0 + r) * n + pc;
            for (int k = 0; k < kc; k++) d[(size_t)k * MR + r] = src[k];
        }
        for (int r = rows; r < MR; r++)
            for (int k = 0; k < kc; k++) d[(size_t)k * MR + r] = 0.0f;
    }
}

static void packB(const float *B, float *Bp, int n, int npad, int s)
{
    int j0 = s * NR, cols = imin(NR, n - j0);
    for (int pc = 0; pc < n; pc += KC) {
        int kc = imin(KC, n - pc);
        float *d = Bp + (size_t)pc * npad + (size_t)s * NR * kc;
        for (int k = 0; k < kc; k++) {
            float *dk = d + (size_t)k * NR;
            memcpy(dk, B + (size_t)(pc + k) * n + j0, sizeof(float) * cols);
            for (int j = cols; j < NR; j++) dk[j] = 0.0f;
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    if (!g_nt) g_nt = get_threads();

    int nsA = (n + MR - 1) / MR, nsB = (n + NR - 1) / NR;
    int mpad = nsA * MR, npad = nsB * NR;

    g_Ap = grow(g_Ap, &g_Acap, (size_t)mpad * n);
    g_Bp = grow(g_Bp, &g_Bcap, (size_t)npad * n);
    float *Ap = g_Ap, *Bp = g_Bp;

    if (!Ap || !Bp) {   /* allocation failure: plain fallback */
        for (int i = 0; i < n; i++) {
            float *c = C + (size_t)i * n;
            for (int j = 0; j < n; j++) c[j] = 0.0f;
            for (int k = 0; k < n; k++) {
                float a = A[(size_t)i * n + k];
                const float *b = B + (size_t)k * n;
                for (int j = 0; j < n; j++) c[j] += a * b[j];
            }
        }
        return;
    }

    int nib = (nsA + MB - 1) / MB, njb = (nsB + NB - 1) / NB;
    int ntasks = nib * njb;
    int nt = (n < 96) ? 1 : g_nt;

#pragma omp parallel num_threads(nt)
    {
#pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < nsA + nsB; t++) {
            if (t < nsA) packA(A, Ap, n, mpad, t);
            else         packB(B, Bp, n, npad, t - nsA);
        }

        float tmp[MR * NR] __attribute__((aligned(64)));

#pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < ntasks; t++) {
            int ib = t / njb, jb = t % njb;
            int s0 = ib * MB, s1 = imin(s0 + MB, nsA);
            int q0 = jb * NB, q1 = imin(q0 + NB, nsB);
            for (int pc = 0; pc < n; pc += KC) {
                int kc = imin(KC, n - pc);
                int acc = pc > 0;
                const float *Apb = Ap + (size_t)pc * mpad;
                const float *Bpb = Bp + (size_t)pc * npad;
                for (int q = q0; q < q1; q++) {
                    const float *b = Bpb + (size_t)q * NR * kc;
                    int j0 = q * NR, nc = imin(NR, n - j0);
                    for (int s = s0; s < s1; s++) {
                        const float *a = Apb + (size_t)s * MR * kc;
                        int i0 = s * MR, mr = imin(MR, n - i0);
                        float *cp = C + (size_t)i0 * n + j0;
                        if (mr == MR && nc == NR) {
                            kern(kc, a, b, cp, n, acc);
                        } else {
                            kern(kc, a, b, tmp, NR, 0);
                            for (int i = 0; i < mr; i++) {
                                float *cr = cp + (size_t)i * n;
                                const float *tr = tmp + i * NR;
                                if (acc) for (int j = 0; j < nc; j++) cr[j] += tr[j];
                                else     for (int j = 0; j < nc; j++) cr[j] = tr[j];
                            }
                        }
                    }
                }
            }
        }
    }
}
